examples.template:
Row(
    modifier = Modifier.semantics { contentDescription = {{label}} },
    horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
) {
    MonarchChip(
        text = {{options.0.label}},
        selected = {{options.0.value}} in pressed,
        onSelectedChange = { on -> pressed = if (on) pressed + {{options.0.value}} else pressed - {{options.0.value}} },
    )
    MonarchChip(
        text = {{options.1.label}},
        selected = {{options.1.value}} in pressed,
        onSelectedChange = { on -> pressed = if (on) pressed + {{options.1.value}} else pressed - {{options.1.value}} },
    )
    MonarchChip(
        text = {{options.2.label}},
        selected = {{options.2.value}} in pressed,
        onSelectedChange = { on -> pressed = if (on) pressed + {{options.2.value}} else pressed - {{options.2.value}} },
    )
}

