MonarchSegmentedControl(modifier = Modifier.semantics { contentDescription = "Alignment" }) {
    options.forEach { option ->
        val selected = option == alignment
        Segment(
            selected = selected,
            onClick = { alignment = if (selected) null else option },
            label = option,
        )
    }
}
